def solve(n=9, fixed={3:1}):
    sol=[-1]*n
    def bt(r):
        if r==n: return True
        cands=[fixed[r]] if r in fixed else range(n)
        for c in cands:
            ok=True
            for i in range(r):
                if sol[i]==c or abs(sol[i]-c)==r-i:
                    ok=False;break
            if ok:
                sol[r]=c
                if bt(r+1): return True
        return False
    if bt(0): return sol
print(solve())
